// Grab the snippet text from the input
const snippet = $input.first().json.messages[0].snippet;

// Regex to capture everything between "I saw that " and " was present at your"
// 'i' makes it case-insensitive
const regex = /I saw that\s+(.*?)\s+was present at your/i;
const match = snippet.match(regex);

// If a match is found, clean up any extra spacing, otherwise return null
const extractedName = match ? match[1].trim() : null;

return {
  json: {
    extractedName: extractedName
  }
};

