parameters.query:
SELECT (
  SELECT DISTINCT created_at::date 
  FROM follow_up_seq_email_threads_cache 
  LIMIT 1
) = CURRENT_DATE AS is_today;

SELECT * FROM follow_up_seq_email_threads_cache
WHERE jsonb_array_length(messages) = 1 
  AND to_timestamp((messages -> 0 ->> 'internalDate')::numeric / 1000) <= NOW() - INTERVAL '2.5 days';

SELECT * FROM follow_up_seq_email_threads_cache
WHERE jsonb_array_length(messages) = 2 
  AND to_timestamp((messages -> 1 ->> 'internalDate')::numeric / 1000) <= NOW() - INTERVAL '4.5 days';

SELECT * FROM follow_up_seq_email_threads_cache
WHERE jsonb_array_length(messages) = 3 
  AND to_timestamp((messages -> 2 ->> 'internalDate')::numeric / 1000) <= NOW() - INTERVAL '4.5 days';
